// Ps3p: menu music and interface sounds. All audio files bundled in Ps3p/Audio are
// original and generated by tools/make_audio.py.

import AVFoundation
import Foundation

@MainActor
final class Ps3pAudio {
    static let shared = Ps3pAudio()

    enum Effect: String, CaseIterable {
        case boot = "ps3p_boot"
        case launch = "ps3p_launch"
        case cursor = "snd_cursor"
        case decide = "snd_decide"
        case cancel = "snd_cancel"
        case ok = "snd_system_ok"
        case error = "snd_system_ng"
    }

    // App preferences, kept apart from the core's settings.
    static let musicEnabledKey = "ps3p.audio.musicEnabled"
    static let musicVolumeKey = "ps3p.audio.musicVolume"
    static let effectsEnabledKey = "ps3p.audio.effectsEnabled"
    static let effectsVolumeKey = "ps3p.audio.effectsVolume"

    private var music: AVAudioPlayer?
    private var effects: [Effect: [AVAudioPlayer]] = [:]
    private var musicWanted = false
    private var lastCursor = Date.distantPast

    private init() {
        let defaults = UserDefaults.standard
        defaults.register(defaults: [
            Self.musicEnabledKey: true,
            Self.musicVolumeKey: 0.45,
            Self.effectsEnabledKey: true,
            Self.effectsVolumeKey: 0.7,
        ])
    }

    var musicEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: Self.musicEnabledKey) }
        set {
            UserDefaults.standard.set(newValue, forKey: Self.musicEnabledKey)
            newValue && musicWanted ? startMenuMusic() : fadeOutMusic(pauseOnly: true)
        }
    }

    var musicVolume: Float {
        get { UserDefaults.standard.float(forKey: Self.musicVolumeKey) }
        set {
            UserDefaults.standard.set(newValue, forKey: Self.musicVolumeKey)
            music?.volume = newValue
        }
    }

    var effectsEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: Self.effectsEnabledKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.effectsEnabledKey) }
    }

    var effectsVolume: Float {
        get { UserDefaults.standard.float(forKey: Self.effectsVolumeKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.effectsVolumeKey) }
    }

    // MARK: Music

    /// Starts (or resumes) the looping menu music with a fade-in.
    func startMenuMusic(fadeIn: TimeInterval = 2.0) {
        musicWanted = true
        guard musicEnabled else { return }
        if music == nil {
            guard let url = Bundle.main.url(forResource: "ps3p_menu_music", withExtension: "m4a"),
                  let player = try? AVAudioPlayer(contentsOf: url) else { return }
            player.numberOfLoops = -1
            player.prepareToPlay()
            music = player
        }
        guard let music, !music.isPlaying else { return }
        music.volume = 0
        music.play()
        music.setVolume(musicVolume, fadeDuration: fadeIn)
    }

    /// Fades the music out; a game start pauses it so the loop resumes where it was.
    func stopMenuMusic(fadeOut: TimeInterval = 0.8) {
        musicWanted = false
        fadeOutMusic(pauseOnly: true, duration: fadeOut)
    }

    private func fadeOutMusic(pauseOnly: Bool, duration: TimeInterval = 0.6) {
        guard let music, music.isPlaying else { return }
        music.setVolume(0, fadeDuration: duration)
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(duration + 0.05))
            guard let self, let current = self.music, !self.musicWanted || !self.musicEnabled else { return }
            pauseOnly ? current.pause() : current.stop()
        }
    }

    // MARK: Effects

    func play(_ effect: Effect) {
        guard effectsEnabled else { return }
        // Fast scrolling would otherwise stack dozens of ticks.
        if effect == .cursor {
            let now = Date()
            guard now.timeIntervalSince(lastCursor) > 0.045 else { return }
            lastCursor = now
        }
        let pool = effects[effect] ?? []
        if let idle = pool.first(where: { !$0.isPlaying }) {
            idle.volume = effectsVolume
            idle.currentTime = 0
            idle.play()
            return
        }
        guard pool.count < 4,
              let url = Bundle.main.url(forResource: effect.rawValue, withExtension: "wav"),
              let player = try? AVAudioPlayer(contentsOf: url) else { return }
        player.volume = effectsVolume
        player.prepareToPlay()
        player.play()
        effects[effect, default: []].append(player)
    }

    /// Gives the emulator core's own overlay sounds (snd_*.wav in its config folder)
    /// the bundled Ps3p set, without replacing anything the user imported.
    func installCoreSounds(into folder: URL) {
        let manager = FileManager.default
        try? manager.createDirectory(at: folder, withIntermediateDirectories: true)
        let names = SoundRouting.menuNames + [SoundRouting.trophyName]
        for name in names {
            let destination = folder.appendingPathComponent(name + ".wav")
            guard !manager.fileExists(atPath: destination.path),
                  let source = Bundle.main.url(forResource: name, withExtension: "wav") else { continue }
            try? manager.copyItem(at: source, to: destination)
        }
    }
}
